use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Exp {
    Const(i128),
    Var(String),
    Plus(Box<Exp>, Box<Exp>),
    Mult(Box<Exp>, Box<Exp>),
}

/// Evaluate an expression under a store.
/// If a variable is missing from the store, it evaluates to -1.
pub fn eval(e: &Exp, store: &HashMap<String, i128>) -> i128 {
    match e {
        Exp::Const(c) => *c,
        Exp::Var(name) => store.get(name).copied().unwrap_or(-1),
        Exp::Plus(a, b) => eval(a, store) + eval(b, store),
        Exp::Mult(a, b) => eval(a, store) * eval(b, store),
    }
}

/// Perform a single-step peephole optimization at the root only.
/// Does not traverse into sub-expressions.
pub fn optimize(e: Exp) -> Exp {
    match e {
        Exp::Mult(a, b) => {
            // Only match at the root; keep children as-is unless returned directly.
            match (&*a, &*b) {
                // Absorbing element: 0 * x = 0, x * 0 = 0
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),

                // Neutral element: 1 * x = x
                (Exp::Const(1), _) => (*b).clone(),
                (_, Exp::Const(1)) => (*a).clone(),

                // Constant folding: c1 * c2
                (Exp::Const(c1), Exp::Const(c2)) => Exp::Const(c1 * c2),

                _ => Exp::Mult(a, b),
            }
        }
        Exp::Plus(a, b) => match (&*a, &*b) {
            // Neutral element: 0 + x = x, x + 0 = x
            (Exp::Const(0), _) => (*b).clone(),
            (_, Exp::Const(0)) => (*a).clone(),

            // Constant folding: c1 + c2
            (Exp::Const(c1), Exp::Const(c2)) => Exp::Const(c1 + c2),

            _ => Exp::Plus(a, b),
        },
        other => other,
    }
}

/// Checks (for this single expression and store) that optimization preserves evaluation.
/// This is the executable counterpart of the requested correctness statement.
pub fn optimize_correct(e: Exp, s: &HashMap<String, i128>) -> bool {
    let v1 = eval(&e, s);
    let opt = optimize(e);
    let v2 = eval(&opt, s);
    v1 == v2
}